css:
@import url('https://fonts.googleapis.com/css2?family=Metamorphous&display=swap');

@font-face {
  font-family: 'Alchemist';
  src: url('Alchemist-Regular.eot');
  src: local('Alchemist'), local('Alchemist-Regular'),
       url('Alchemist-Regular.eot?#iefix') format('embedded-opentype'),
       url('Alchemist-Regular.woff2') format('woff2'),
       url('Alchemist-Regular.woff') format('woff'),
       url('Alchemist-Regular.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
}

/* =========================================================
   FRONT COVER
   ========================================================= */

.page:has(.frontCover) {
  padding: 0 !important;
  column-count: 1 !important;
  background: #0b0b0b !important;
  background-image: none !important;
  overflow: hidden !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
}

.page:has(.frontCover)::after {
  display: none !important;
}

.frontCover {
  position: absolute !important;
  inset: -10px !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  z-index: 1 !important;
  background: #0b0b0b !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}

/* Keep the artwork at exactly the current position/crop. */
.frontCover .cover-art {
  position: absolute !important;
  top: 52% !important;
  left: 50% !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: translate(-50%, -54%) scale(1.03) !important;
  object-fit: cover !important;
  object-position: center center !important;
  z-index: 0 !important;
}



.frontCover .cover-copy {
  position: absolute !important;
  inset: 0 !important;
  z-index: 2 !important;
  color: #ffffff;
  text-align: center;
  pointer-events: none;
  background: transparent !important;
  box-shadow: none !important;
}

.frontCover .cover-copy *,
.frontCover .cover-footer,
.frontCover .cover-footer * {
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
  filter: none !important;
}

.frontCover .cover-kicker {
  position: absolute;
  top: 24px;
  left: 22px;
  margin: 0;
  font-family: "Great Vibes", cursive;
  font-size: 16pt; /* script fonts read smaller visually, bump size up */
  font-weight: 400; /* most scripts only ship one weight */
  line-height: 1;
  letter-spacing: 0.5px; /* scripts need less/no extra spacing */
  color: #ffffff;
  text-shadow: 1px 1px 0 #000000, 2px 2px 0 rgba(0,0,0,0.72);
}

.frontCover .cover-title-group {
  position: absolute;
  top: 606px;
  left: 0;
  width: 100%;
  transform: rotate(-0deg);
}

/* IMPORTANT: every shadowed cover text below uses the SAME rendering
   recipe as ALCHEMIST. Only size/spacing differs. */
.frontCover .cover-title,
.frontCover .cover-tagline,
.frontCover .cover-version,
.frontCover .cover-credit {
  font-family: beaufort-pro, serif;
  font-weight: 900;
  font-style: italic;
  color: #ffffff;
  -webkit-text-stroke: 0.8px rgba(0,0,0,0.95);
  text-shadow: 2px 2px 0 #000000, 4px 4px 0 rgba(0,0,0,0.78);
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  filter: none !important;
}

.frontCover .cover-title {
  margin: 0;
  font-family: "Metamorphous", serif !important;
  font-weight: normal !important;
  font-style: normal !important;
  font-size: 40pt;
  line-height: 0.95;
  letter-spacing: 1px;
  white-space: nowrap;
}

.frontCover .cover-divider {
  display: block;
  width: 330px;
  height: 3px;
  margin: 12px auto 14px auto;
  background: #f7f7f7 !important;
  box-shadow: 0 2px 0 rgba(0,0,0,0.65) !important;
}

.frontCover .cover-subtitle {
  margin: 0;
  font-family: "Metamorphous", serif !important;
  font-weight: normal !important;
  font-style: normal !important;
  font-size: 16pt;
  line-height: 1;
  letter-spacing: 0.3px;
  color: #ffffff;
  text-transform: uppercase;
  white-space: nowrap;
  -webkit-text-stroke: 0.5px rgba(0,0,0,0.1);
  text-shadow: 1px 1px 0 #000000, 3px 3px 0 rgba(0,0,0,0.70);
}

.frontCover .cover-tagline,
.frontCover .cover-version,
.frontCover .cover-credit {
  /* EXACT rendering recipe from the working "An Unofficial Class for Nimble" text. */
  position: absolute;
  margin: 0;
  padding: 0 !important;
  font-family: "Avenir Condensed", "Avenir Next Condensed", sans-serif;
  font-size: 10.25pt;
  font-weight: 700;
  font-style: normal;
  line-height: 1;
  letter-spacing: 1.1px;
  text-transform: uppercase;
  color: #ffffff;
  text-shadow: 1px 1px 0 #000000, 2px 2px 0 rgba(0,0,0,0.72);
  -webkit-text-stroke: 0 !important;
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  filter: none !important;
  right: auto;
}

/* Only position/size differs from the kicker. */
.frontCover .cover-tagline {
  top: auto;
  left: 50%;
  bottom: 88px;
  width: 90%;
  transform: translateX(-50%);
  font-size: 11.4pt;
  line-height: 1.06;
  letter-spacing: 0;
  text-transform: none;
  white-space: nowrap;
}

.frontCover .cover-version {
  top: auto;
  left: 50%;
  bottom: 43px;
  width: auto;
  transform: translateX(-50%);
  font-size: 20pt;
  font-style: italic;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
}

.frontCover .cover-credit {
  top: auto;
  left: 50%;
  bottom: 35px;
  width: auto;
  transform: translateX(-50%);
  font-size: 8.8pt;
  line-height: 1;
  letter-spacing: 0;
  text-transform: none;
  white-space: nowrap;
}

/* Vector logo: no PNG alpha layer, no filter, no drop shadow. */
.frontCover .cover-nimble-logo {
  position: absolute !important;
  right: 30px !important;
  bottom: 715px !important;
  width: 146px !important;
  height: auto !important;
  z-index: 4 !important;
  overflow: visible !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
}

.frontCover .cover-nimble-logo path {
  fill: #ffffff !important;
  stroke: none !important;
}

.page:has(.frontCover) .pageNumber {
  display: none !important;
}

@media print {
  @page { margin: 0; }
  html, body { margin: 0 !important; padding: 0 !important; }
  .page:has(.frontCover) {
    margin: 0 !important;
    padding: 0 !important;
    background: #0b0b0b !important;
    box-shadow: none !important;
    border: none !important;
    outline: none !important;
  }
  .frontCover,
  .frontCover * {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }
}

/* ---------- LEGAL / INSIDE COVER ---------- */

.insideCover {
  display: none;
}

.legal-page h1 {
  margin: 0 0 12px 0;
  text-align: center;
  font-family: beaufort-pro, serif;
  font-weight: 900;
  font-style: italic;
  font-size: 28pt;
  line-height: 1;
  color: #211f20;
  text-transform: uppercase;
}

.legal-page .legal-subtitle {
  margin: 0 0 18px 0;
  text-align: center;
  font-family: "Avenir Condensed", "Avenir Next Condensed", sans-serif;
  font-size: 11pt;
  line-height: 1.15;
  color: #404040;
}

.legal-page .legal-rule {
  width: 100%;
  height: 1px;
  background: rgba(33,31,32,0.4);
  margin: 10px 0 16px 0;
}

.legal-page .legal-block {
  margin-bottom: 12px;
  font-family: "Avenir Condensed", "Avenir Next Condensed", sans-serif;
  font-size: 10.2pt;
  line-height: 1.22;
  color: #211f20;
}

.legal-page .legal-block strong {
  font-family: beaufort-pro, serif;
  font-weight: 900;
  font-size: 11pt;
}

.legal-page .legal-note {
  margin-top: 14px;
  font-size: 9.5pt;
  line-height: 1.2;
  color: #3b3b3b;
}

.legal-page .legal-small {
  font-size: 9.2pt;
  line-height: 1.18;
  color: #4b4b4b;
}

.legal-page .legal-list {
  margin: 6px 0 0 16px;
}

.legal-page .legal-list li {
  margin: 3px 0;
}



.legal-page {
  text-align: left;
}

.legal-page .legal-logo {
  display: block;
  width: 300px;
  height: auto;
  margin: 0 auto 12px auto;
  opacity: 0.92;
}

.legal-page .legal-disclaimer-block {
  padding: 8px 10px;
  border: 1px solid rgba(33,31,32,0.18);
  background: rgba(87, 42, 35, 0.05);
  border-radius: 8px;
}

/* =========================================================
   ALCHEMIST BLURB PAGE
   ========================================================= */

.alchemist-blurb-page {
  position: relative;
  width: 100%;
  box-sizing: border-box;
  color: #000000;
  text-align: center;
}



/* =========================================================
   MAIN TITLE
   ========================================================= */

.alchemist-blurb-title {
  font-family: beaufort-pro;
  font-size: 32pt;
  font-weight: 900;
  font-style: italic;
  font-variant-caps: small-caps;
  line-height: 0.9;
  text-align: center;
}

/* =========================================================
   INTRO / STORY TEXT
   ========================================================= */

.alchemist-blurb-copy {
  width: 80%;
  margin:  auto;

  font-family: "EB Garamond", "Garamond", "Palatino Linotype",
               "Book Antiqua", Palatino, serif;

  font-size: 13px;
  font-weight: 900;
  line-height: 1.24;
  letter-spacing: 0.05px;

  text-align: left !important;

  hyphens: auto;
  -webkit-hyphens: auto;
}

/* Longer paragraphs: justified */
.alchemist-blurb-copy .blurb-paragraph {
  display: block;
  width: 100%;
  margin: 0 0 7px 0;

  text-align: justify !important;
  text-align-last: left !important;
}

/* Short standalone lines: always flush left */
.alchemist-blurb-copy .blurb-line {
  display: block;
  width: 100%;
  margin: 0 0 7px 0;

  text-align: left !important;
}

.alchemist-blurb-copy > div:last-child {
  margin-bottom: 0;
}

/* =========================================================
   HORIZONTAL SEPARATORS
   ========================================================= */

.alchemist-blurb-rule {
  width: 100%;
  height: 1px;
  margin: 30px auto 30px auto;
  background: rgb(87, 42, 35);
}

.alchemist-blurb-rule-bottom {
  margin-top: 20px;
  margin-bottom: 40px;
}

/* =========================================================
   THREE CORE FEATURE COLUMNS
   ========================================================= */

.alchemist-blurb-columns {
  width: 100%;
  margin: 0 auto;

  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  gap: 19px;
}

.alchemist-blurb-column {
  flex: 1 1 0;
  min-width: 0;
  width: auto;
  text-align: center;
}

/* =========================================================
   FEATURE ICONS
   ========================================================= */

.alchemist-blurb-icon {
  height: 74px;
  margin: 0 auto 12px auto;

  display: flex;
  align-items: center;
  justify-content: center;
}

.alchemist-blurb-icon img {
  display: block;
  width: 66px;
  height: 66px;
  object-fit: contain;
}

/* =========================================================
   FEATURE TEXT
   ========================================================= */

.alchemist-blurb-feature {
  font-family: "Avenir Condensed";
  font-size: 10pt;
  line-height: 1.12;
  text-align: justify;
  hyphens: auto;
}

.alchemist-blurb-feature strong {
  font-size: 13.5px;
  font-weight: 700;
}

/* Visually normalize the three class icons */
.alchemist-blurb-icon .class-wheel-icon {
  transform: scale(0.88);
}

.alchemist-blurb-icon .class-phoenix-icon {
  transform: scale(1.08);
}

.alchemist-blurb-icon .class-death-icon {
  transform: scale(1.00);
}

/* =========================================================
   BOTTOM CLASS SUMMARY
   ========================================================= */

.alchemist-blurb-summary {
  font-family: "Avenir Condensed";
  width: 72%;
  margin: 0 auto;

  font-size: 10pt;
  line-height: 1.12;
  text-align: center;
}

/* =========================================================
   CLASS COMPLEXITY
   ========================================================= */

.alchemist-complexity {
  display: flex;
  justify-content: center;
  align-items: center;

  gap: 2px;
  margin: 8px auto 0 auto;

  line-height: 0;
}

.alchemist-complexity img {
  display: block;
  width: auto;
  height: 24px;
}


/* =========================================================
   CLASS CENTER ALIGNED
   ========================================================= */

/* Was left aligned before */

.classDetails {
  text-align: center;
}


/* =========================================================
   DICE ICONS - SHARED BASE
   ========================================================= */

/* Basic styling shared by all dice icons */
.die {
display: inline-block;
background-position: center;
background-repeat: no-repeat;
background-size: contain;
}


/* =========================================================
   DICE ICON SIZES
   ========================================================= */
/* Compact die - potion formula tables */
.die-10 {
  width: 10px;
  height: 10px;
  vertical-align: -1px;
}
/* Small inline die - 12px */
.die-12 {
width: 12px;
height: 12px;
vertical-align: -2px;
}

/* Standard inline die - 14px */
.die-14 {
width: 14px;
height: 14px;
vertical-align: -2px;
}

/* Large inline die - 20px */
.die-20 {
width: 20px;
height: 20px;
vertical-align: -4px;
}

/* Extra large die - 28px */
.die-28 {
width: 28px;
height: 28px;
vertical-align: -6px;
}

/* Fill the full width and height of the parent container */
.die-full {
display: block;
width: 100%;
height: 100%;
margin: 0 auto;
vertical-align: 0;
}


