/* =========================================================
   DICE FORMULAE
   ========================================================= */

/* Keeps dice and formula symbols consistently aligned */
.dice-formula {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  white-space: nowrap;
  line-height: 1;
  width: max-content;
  max-width: 100%;
}

/* Prevent dice from growing or shrinking inside formulae */
.dice-formula .die {
  display: inline-block;
  flex-grow: 0;
  flex-shrink: 0;
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
}

/* Fixed 12px dice inside potion formulae */
.dice-formula .die-12 {
  width: 12px !important;
  height: 12px !important;
  min-width: 12px;
  min-height: 12px;
  max-width: 12px;
  max-height: 12px;
  flex-basis: 12px;
  aspect-ratio: 1 / 1;
  vertical-align: 0;
}

