/* =========================================================
   HOMUNCULUS NOTE
   ========================================================= */

.homunculus-note,
.homunculus-note * {
  font-family: "Avenir Condensed" !important;
  font-size: 9.5px !important;
  line-height: 1.08 !important;
}


/* =========================================================
   HOMUNCULUS TRACKER
   ========================================================= */

.homunculus-sheet {
  width: 100%;
  color: #000000;
}

.homunculus-sheet .sheet-title {
  text-align: center;
  font-family: beaufort-pro;
  font-size: 32px;
  font-weight: 900;
  line-height: 1;
  margin: 0 0 12px 0;
}

.homunculus-sheet table {
  position: relative;
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 15px;
  line-height: 1;
}

.homunculus-sheet th {
  font-family: beaufort-pro;
  padding: 0px -1px 0px 0px;
  text-align: center;
  font-style: italic;
  font-weight: 900;
  font-size: 12.5px;
}

.homunculus-sheet td {
  padding: 6px 6px;
  vertical-align: middle;
}


/* Print-safe alternating row fill.
   Each shaded cell contains a real SVG rectangle instead of
   a CSS background, so the grey rows print even when
   "Background graphics" are disabled. */
.homunculus-sheet td {
  position: relative;
  overflow: hidden;
}

.homunculus-row-fill {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.homunculus-cell-content {
  position: relative;
  z-index: 1;
  display: inline-block;
}

.homunculus-sheet td.effect-col .homunculus-cell-content {
  display: block;
  width: 100%;
}

/* Homebrew Evolution rows use real SVG images as well. */
.homunculus-inline-die {
  display: inline-block;
  width: 14px;
  height: 14px;
  object-fit: contain;
  vertical-align: -3px;
}

.homunculus-write-line {
  display: inline-block;
  width: 86%;
  height: 12px;
  margin-left: 4px;
  border-bottom: 1px solid #575758;
  vertical-align: -1px;
}

/* Alternating row shading is rendered with actual inline SVGs.
   This remains visible when browser "Background graphics" are disabled. */
.homunculus-sheet tbody tr {
  background: transparent !important;
}

/* Four Catalyst slot columns */
.homunculus-sheet .slot-col {
