.slot-box.lvl3 .slot-die-img {
  filter: invert(15%);
}

/* LVL 7 */
.slot-box.lvl7 .slot-die-img {
  filter: invert(30%);
}

/* LVL 11 */
.slot-box.lvl11 .slot-die-img {
  filter: invert(45%);
}

/* LVL 15 - lightest */
.slot-box.lvl15 .slot-die-img {
  filter: invert(60%);
}

