/* =========================================================
   PDF VECTOR LAYERS
   The crisp Revelation cards use positioned child layers
   inside {{wide}}. Apply the same pattern to the other
   wide content so Chrome keeps text/SVGs as separate paint
   layers during PDF export.
   ========================================================= */

/* Direct content inside a wide block */
.wide > div,
.wide > table {
  position: relative;
}

/* Tables should always be their own positioned paint layer */
.wide table,
.pdf-vector {
  position: relative;
}

/* Subclass SVG artwork should also be painted separately */
.essence-art {
  position: relative;
}

/* =========================================================
   VECTOR-SAFE SECTION BANNERS
   Keep clip-path on the background only, not on the text.
   ========================================================= */

.vector-banner {
  font-family: beaufort-pro;
  position: relative;
  margin: 0 auto 12px auto;
  padding: 3px 18px;
  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.vector-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(136, 97, 99, 0.75);
  clip-path: polygon(10% 0,90% 0,100% 50%,90% 100%,10% 100%,0 50%);
}

.vector-banner > span {
  position: relative;
  display: block;
}

.vector-banner-170 {
  width: 140px;
}

.vector-banner-100 {
  width: 60px;
  font-size: 14px;
}

.vector-banner-180 {
  width: 180px;
}

.vector-banner-200 {
  width: 200px;
}


.vector-banner-250 {
  width: 250px;
}

.vector-banner-280 {
  width: 280px;
}

.vector-class {
  font-family: beaufort-pro;
  position: relative;
  margin: 0 auto 12px auto;
  padding: 3px 18px;
  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.vector-class::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(136, 97, 99, 0.75);
  clip-path: polygon(10% 0,90% 0,100% 50%,90% 100%,10% 100%,0 50%);
}

.vector-class > span {
  position: relative;
  display: block;
}

.vector-class-140 {
  width: 140px;
}

.vector-class-270 {
  width: 270px;
}

/* =========================================================
   PRINT-SAFE VECTOR BANNER
   Shape AND text live inside the same inline SVG, so there
   is no stacking-order problem and no reliance on CSS
   background printing.
   ========================================================= */

.print-vector-banner {
  font-family: beaufort-pro;
  position: relative;
  box-sizing: border-box;
  height: 22px;
  margin: 0 auto 12px auto;

  display: flex;
  align-items: center;
  justify-content: center;

  text-align: center;
  color: #ffffff;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.print-vector-banner-svg {
  position: absolute;
  inset: 0;
  z-index: 0;

  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.print-vector-banner > span {
  position: relative;
  z-index: 1;

  display: block;
  color: inherit;
  font: inherit;
  line-height: 1;
}

.print-vector-banner-250 {
  width: 235px;
}


.print-vector-banner-280 {
  width: 280px;
}


/* =========================================================
   POTION FORMULAE SHEET
   ========================================================= */

.potion-sheet {
  position: relative;
  width: 100%;
  margin: 10px auto 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-auto-rows: 136px;
  gap: 9px 10px;
  box-sizing: border-box;
}

/* =========================================================
   POTION CARD
   Fixed dimensions keep every card identical, regardless
   of effect length or the number of formula dice.
   ========================================================= */

.potion-card {
  font-family: "Avenir Condensed";
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 136px;
  min-height: 136px;
  max-height: 136px;
  padding: 5px 5px 5px 5px;
  border: 1.3px solid #575758;
  border-radius: 9px;
  display: flex;
  flex-direction: column;
  text-align: center;
  color: #000000;
  overflow: hidden;
  break-inside: avoid;
}

/* =========================================================
   POTION NAME
   ========================================================= */

.potion-name {
  font-family: beaufort-pro;
  flex: 0 0 15px;
  height: 15px;
  margin: 0 0px 0px 0px;
  font-size: 12.2px;
  font-weight: 900;
  line-height: 1.05;
  text-align: center;
  white-space: nowrap;
}

/* =========================================================
   POTION EFFECT
   Long effects receive smaller type through modifier classes.
   ========================================================= */

.potion-effect {
  flex: 1 1 auto;
  min-height: 0;
  padding: 0 2px;
  font-size: 10px;
  line-height: 1.1;
  text-align: center;
  hyphens: auto;
  -webkit-hyphens: auto;
}

.potion-effect.potion-effect-small {
  font-size: 10px;
  line-height: 1.1;
}

.potion-effect.potion-effect-xsmall {
  font-size: 10px;
  line-height: 1.1;
}

/* =========================================================
   POTION FORMULA DICE
   The whole formula area has a fixed height so larger
   recipes never increase the card or grid row height.
   Dice are intentionally larger for quick table readability.
   ========================================================= */

.potion-dice {
  flex: 0 0 44px;
  height: 44px;
  min-height: 44px;
  max-height: 44px;
  margin: 1px 0 1px 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 1px;
  line-height: 1;
  overflow: hidden;
}

.potion-dice-row {
  height: 21px;
  min-height: 21px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 2px;
  white-space: nowrap;
  line-height: 1;
}

.potion-dice img {
  display: block;
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  max-width: 20px;
  max-height: 20px;
  object-fit: contain;
  flex: 0 0 20px;
}

.potion-symbol {
  display: inline-block;
  flex: 0 0 auto;
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1;
  color: #000000;
}

.potion-or {
  display: inline-block;
  flex: 0 0 auto;
  margin-right: 1px;
  font-size: 8.8px;
  font-weight: 700;
  line-height: 1;
  color: #777372;
}

/* D8 formula dice need a little more visual weight than the D6 icons. */
.potion-souls .potion-dice img {
  width: 28px;
  height: 28px;
  min-width: 28px;
  min-height: 28px;
  max-width: 28px;
  max-height: 28px;
  flex-basis: 28px;
}

/* Antidote: center both alternatives on the same vertical axis.
   OR sits between the rows without taking up horizontal space. */
.potion-antidote {
  position: relative;
}

.potion-antidote .potion-dice-row {
  width: 100%;
  justify-content: center;
}

.potion-antidote .potion-or-between {
  position: absolute;
  left: 7px;
  top: 50%;
  margin: 0;
  transform: translateY(-50%);
}

/* =========================================================
   POTION META FOOTER
   Tier and source now share the bottom line.
   ========================================================= */

.potion-meta {
  flex: 0 0 12px;
  height: 12px;
  min-height: 12px;
  margin-top: 1px;
  padding: 3px 2px 0 2px;
  border-top: 1px solid rgba(87, 87, 88, 0.23);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 5px;
  color: #85817e;
  line-height: 1;
}

.potion-meta-tier {
  flex: 0 0 auto;
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.2px;
  white-space: nowrap;
}

.potion-meta-source {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 6.3px;
  font-weight: 700;
  letter-spacing: 0.18px;
  text-align: right;
  white-space: nowrap;
}

/* =========================================================
   POTION SHEET NOTE
   ========================================================= */

.potion-sheet-note {
  width: 92%;
  margin: 8px auto 0 auto;
  font-size: 7.4px;
  font-style: italic;
  line-height: 1.1;
  text-align: center;
  color: #777372;
}


/* =========================================================
   HOMEBREW POTION ROWS
   ========================================================= */

/* Separator between published formulae and blank homebrew cards. */
.potion-homebrew-divider {
  position: relative;
  width: 96%;
  height: 1px;
  margin: 8px auto 6px auto;
  background: rgb(87, 42, 35);
}

/* One additional fixed row per potion page. */
.potion-homebrew-sheet {
  margin-top: 0;
  grid-auto-rows: 136px;
}

/* Keep the blank cards exactly the same size as all other potion cards. */
.potion-homebrew {
  height: 136px;
  min-height: 136px;
  max-height: 136px;
}

/* Potion of ______ : leave a long writing line for a handwritten name. */
.potion-homebrew-name {
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 4px;
  padding: 0 3px;
  text-align: left;
  white-space: nowrap;
}

.potion-homebrew-name > span:first-child {
  flex: 0 0 auto;
}

.potion-homebrew-name-line {
  display: inline-block;
  flex: 1 1 auto;
  min-width: 0;
  height: 10px;
  border-bottom: 1px solid rgba(87, 87, 88, 0.65);
}

/* Empty writing area for the custom effect and Catalyst formula. */
.potion-homebrew-space {
  flex: 1 1 auto;
  min-height: 0;
}


