  display: grid;
  grid-template-columns: repeat(6, 34px);
  justify-content: center;
  gap: 22px;
}

.steel-die-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: 1.4px solid #211f20;
  font-family: beaufort-pro;
  font-weight: 900;
  font-size: 14.5px;
  line-height: 1;
  background: rgba(255,255,255,0.45);
}

.steel-augment-table,
.steel-properties-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 11.1px;
  line-height: 1.12;
}

.steel-augment-table th,
.steel-augment-table td,
.steel-properties-table td {
  border: 1px solid #211f20;
  padding: 2px 3px;
  vertical-align: middle;
}

.steel-augment-table th {
  font-family: beaufort-pro;
  font-weight: 900;
  font-size: 11px;
  text-align: center;
  background: rgba(0,0,0,0.08);
}

.steel-augment-table .dice-col {
  width: 20%;
  text-align: center;
}

.steel-augment-table .augment-col {
  width: 20%;
 text-align: center;
}

.steel-augment-table .effect-col {
  width: 60%;
}

.steel-dice-pair {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
}

.steel-inline-die {
  width: 18px;
  height: 18px;
  object-fit: contain;
  flex: 0 0 auto;
}

.steel-plus {
  font-family: beaufort-pro;
  font-weight: 900;
  font-size: 12px;
  line-height: 1;
}

.steel-properties-table .check-col {
  width: 9%;
  text-align: center;
  padding: 3px;
}

.steel-properties-table .text-col {
  width: 91%;
}

.steel-check-box {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 1.3px solid #211f20;
  vertical-align: middle;
  background: rgba(255,255,255,0.45);
}

.steel-divider-row td {
  font-family: beaufort-pro;
  font-weight: 900;
  font-size: 11px;
  text-align: center;
  background: rgba(0,0,0,0.08);
  padding: 4px 6px;
}

.steel-ironworks-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  border: 1px solid #211f20;
  padding: 5px 6px;
}

.steel-uses-boxes {
  display: grid;
  grid-template-columns: repeat(3, 14px);
  grid-template-rows: repeat(2, 14px);
  gap: 4px;
  flex: 0 0 auto;
  margin-top: 1px;
}

.steel-use-box {
  display: block;
  width: 14px;
  height: 14px;
  border: 1.3px solid #211f20;
  background: rgba(255,255,255,0.45);
}

.steel-ironworks-text {
  flex: 1 1 auto;
  font-size: 11.2px;
  line-height: 1.14;
}

/* =========================================================
   TABLE OF CONTENTS
   ========================================================= */

.page:has(.alchemist-toc) {
  column-count: 1 !important;
}

.alchemist-toc {
  width: 100%;
  color: #211f20;
  position: relative;
  min-height: 0;
  box-sizing: border-box;
  padding-top: 2px;
}

.alchemist-toc-banner {
  margin-bottom: 10px !important;
}

.alchemist-toc-rule {
  width: 88%;
  height: 1.5px;
  margin: 0 auto 24px auto;
  background: #211f20;
  opacity: 0.82;
}

.alchemist-toc-grid {
  display: flex !important;
  flex-direction: row !important;
  align-items: flex-start !important;
  justify-content: space-between !important;
  gap: 34px;
  width: 92%;
  margin: 0 auto;
  box-sizing: border-box;
}

.alchemist-toc-column {
  flex: 0 0 calc((100% - 34px) / 2);
  width: calc((100% - 34px) / 2);
  min-width: 0;
  box-sizing: border-box;
}

.alchemist-toc-section {
  font-family: beaufort-pro;
  font-size: 20px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.3px;
  color: #000000;
  margin: 0 0 11px 0;
  padding-bottom: 5px;
  border-bottom: 2px solid rgba(136,97,99,0.65);
}

.alchemist-toc-section-spaced {
  margin-top: 24px;
}

.alchemist-toc-entry {
  display: flex;
  align-items: baseline;
  width: 100%;
  gap: 6px;
  margin: 0 0 10px 0;
  font-size: 13.5px;
  line-height: 1.12;
}

.alchemist-toc-major {
  font-weight: 700;
}

.alchemist-toc-subentry {
  padding-left: 13px;
  box-sizing: border-box;
  font-style: italic;
}

.alchemist-toc-label {
  flex: 0 1 auto;
  min-width: 0;
}

.alchemist-toc-dots {
  flex: 1 1 auto;
  min-width: 16px;
  border-bottom: 1.5px dotted rgba(33,31,32,0.58);
  transform: translateY(-2px);
}

.alchemist-toc-page {
  flex: 0 0 22px;
  text-align: right;
  font-family: beaufort-pro;
  font-size: 13px;
  font-weight: 900;
}

.alchemist-toc-callout {
  margin-top: 28px;
  padding: 10px 12px 11px 12px;
  border-top: 2px solid rgba(136,97,99,0.75);
  border-bottom: 2px solid rgba(136,97,99,0.75);
  background: rgba(136,97,99,0.08);
}

.alchemist-toc-callout-title {
  font-family: beaufort-pro;
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 1px;
  margin-bottom: 3px;
}

.alchemist-toc-callout-text {
  font-size: 13px;
  line-height: 1.25;
}

.alchemist-toc-mark {
  display: block;
  width: 56px;
  height: auto;
  margin: 48px auto 0 auto;
  opacity: 0.78;
}



/* =========================================================
   SUBCLASS OVERVIEW
   ========================================================= */

.page:has(.alchemist-subclass-overview) {
  column-count: 1 !important;
}

.alchemist-subclass-overview {
  width: 100%;
  box-sizing: border-box;
  color: #211f20;
  overflow: hidden;
}

.alchemist-subclass-overview-intro {
  width: 90%;
  margin: 3px auto 5px auto;
  text-align: center;
  font-family: 'Avenir Condensed';
  font-size: 13px;
  line-height: 1;
}

.alchemist-subclass-list {
  width: 94%;
  margin: 0 auto;
}

.alchemist-subclass-row {
  display: grid;
  grid-template-columns: 22% 1fr 88px;
  gap: 5px;
  align-items: center;
  padding: 5px 5px;
  border-bottom: 1.5px solid rgba(136,97,99,0.42);
  break-inside: avoid;
}

.alchemist-subclass-row:first-child {
  border-top: none;
}

.alchemist-subclass-name {
  font-family: beaufort-pro;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
  text-transform: uppercase;
}

.alchemist-subclass-desc {
  font-family: 'Avenir Condensed';
  font-size: 12.5px;
  line-height: 1.12;
}

.alchemist-subclass-complexity {
  text-align: center;
  white-space: nowrap;
}

.alchemist-subclass-complexity img {
  width: 18px;
  height: 18px;
  object-fit: contain;
  margin: 0 -2px;
  vertical-align: middle;
}



.alchemist-subclass-header {
  width: 94%;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 22% 1fr 88px;
  gap: 12px;
  align-items: end;
  padding: 5px 7px 6px 7px;
  box-sizing: border-box;
  border-top: 1.5px solid rgba(136,97,99,0.62);
  border-bottom: 1.8px solid rgba(136,97,99,0.62);
  font-family: beaufort-pro;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.35px;
}

.alchemist-subclass-header-name,
.alchemist-subclass-header-desc {
  text-align: left;
}

.alchemist-subclass-header-complexity {
  text-align: center;
  white-space: nowrap;
}

/* =========================================================
   FAQ
   ========================================================= */

.alchemist-faq {
  font-family: 'Avenir Condensed';
  color: #211f20;
}

.alchemist-faq-title {
  margin: 0 0 18px 0;
  text-align: center;
  font-family: beaufort-pro;
  font-size: 34px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.5px;
}

.alchemist-faq-intro {
  width: 82%;
  margin: 0 auto 22px auto;
  text-align: center;
  font-size: 13px;
  line-height: 1.2;
}

.alchemist-faq-entry {
  break-inside: avoid;
  margin: 0 0 14px 0;
  padding-top: 6px;
  border-top: 1.5px solid rgba(136,97,99,0.58);
}

.alchemist-faq-entry h3 {
  margin: 0 0 5px 0;
  font-family: beaufort-pro;
  font-size: 16px;
  font-weight: 900;
  line-height: 1.05;
}

.alchemist-faq-entry p {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.22;
}


/* =========================================================
   CLICKABLE PDF TABLE OF CONTENTS
   ========================================================= */

.toc-pdf-anchor {
  display: block;
  width: 0;
  height: 0;
  overflow: hidden;
  line-height: 0;
}

a.alchemist-toc-entry,
a.alchemist-toc-entry:link,
a.alchemist-toc-entry:visited,
a.alchemist-toc-entry:hover,
a.alchemist-toc-entry:active {
  color: inherit !important;
  text-decoration: none !important;
  border: 0 !important;
  outline: 0 !important;
  cursor: default;
}


/* =========================================================
   SUBCLASS OVERVIEW — INTERNAL LINKS
   ========================================================= */

a.alchemist-subclass-link,
a.alchemist-subclass-link:link,
a.alchemist-subclass-link:visited,
a.alchemist-subclass-link:hover,
a.alchemist-subclass-link:active {
  display: block;
  color: inherit !important;
  text-decoration: none !important;
  border: 0 !important;
  outline: 0 !important;
}

/* =========================================================
   PDF OUTLINE / BOOKMARK HEADINGS
   Semantic H1/H2/H3 headings with no visible layout impact.
   Chromium can use these when PDF outline generation is enabled.
   ========================================================= */

.pdf-outline-heading {
  display: block !important;
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
  line-height: 0 !important;
  font-size: 0 !important;
  color: transparent !important;
}

h1.pdf-outline-heading { bookmark-level: 1; }
h2.pdf-outline-heading { bookmark-level: 2; }
h3.pdf-outline-heading { bookmark-level: 3; }


