/* =========================================================
   FLIP PAGE NUMBER SIDES
   ========================================================= */

/* Odd pages: number on the right */
.page:nth-child(odd) .pageNumber {
  left: auto !important;
  right: 0 !important;
}

/* Even pages: number on the left */
.page:nth-child(even) .pageNumber {
  right: auto !important;
  left: 0 !important;
}
